// StructureMap: MedicationOverviewMin -> MedicationOverview (Bundle Profile), R4
// Source : PH4H Logical Model MedicationOverviewMin (compact QR-payload form)
// Target : IHE Pharm MEOW MedicationOverview Bundle (document)
// FHIR version: R4 (4.0.1)
//
// This map composes the two stage maps:
//   1. MedicationOverviewMinToMedicationOverviewLM  (Min  -> IHE LM)
//   2. MedicationOverviewLMToMedicationOverviewBundle (IHE LM -> IHE Bundle)
// via an intermediate MedicationOverviewLM created with create().
//
// Caveats:
//   - Engine support for intermediate scratch variables created via create() varies.
//   - All LM / profile canonicals are IHE Pharm MEOW (r4) on this branch.

map "MedicationOverviewMinToMedicationOverviewBundle" = "http://smart.who.int/ph4h/StructureMap/MedicationOverviewMinToMedicationOverviewBundle"

uses "http://smart.who.int/ph4h/StructureDefinition/MedicationOverviewMin"            alias MedicationOverviewMin        as source
uses "http://profiles.ihe.net/PHARM/MEOW/StructureDefinition/MedicationOverviewLM"    alias MedicationOverviewLM         as produced
uses "http://profiles.ihe.net/PHARM/MEOW/StructureDefinition/MedicationOverview"      alias MedicationOverviewBundle     as target

imports "http://smart.who.int/ph4h/StructureMap/MedicationOverviewMinToMedicationOverviewLM"
imports "http://smart.who.int/ph4h/StructureMap/MedicationOverviewLMToMedicationOverviewBundle"


// ---------------------------------------------------------------------------
// Top-level group: chain Min -> IHE LM -> IHE Bundle
// ---------------------------------------------------------------------------
group MedicationOverviewMinToMedicationOverviewBundle(source src : MedicationOverviewMin, target tgt : MedicationOverviewBundle) {
  src -> create('MedicationOverviewLM') as lm
    then MedicationOverviewMinToMedicationOverviewLM(src, lm),
         MedicationOverviewLMToMedicationOverviewBundle(lm, tgt)               "chainMinToBundle";
}
